PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE `booking_history` (
	`id` text PRIMARY KEY NOT NULL,
	`booking_id` text NOT NULL,
	`action` text NOT NULL,
	`detail` text,
	`user` text,
	`at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`booking_id`) REFERENCES `bookings`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `bookings` (
	`id` text PRIMARY KEY NOT NULL,
	`reference` text NOT NULL,
	`customer_id` text NOT NULL,
	`package_id` text NOT NULL,
	`departure_id` text NOT NULL,
	`type` text NOT NULL,
	`status` text DEFAULT 'draft' NOT NULL,
	`payment_status` text DEFAULT 'unpaid' NOT NULL,
	`pax_adult` integer DEFAULT 0 NOT NULL,
	`pax_child` integer DEFAULT 0 NOT NULL,
	`pax_infant` integer DEFAULT 0 NOT NULL,
	`total_amount` integer DEFAULT 0 NOT NULL,
	`discount` integer DEFAULT 0 NOT NULL,
	`deposit_amount` integer DEFAULT 0 NOT NULL,
	`paid_amount` integer DEFAULT 0 NOT NULL,
	`balance_due` integer DEFAULT 0 NOT NULL,
	`created_by` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `passengers` (
	`id` text PRIMARY KEY NOT NULL,
	`booking_id` text NOT NULL,
	`full_name` text NOT NULL,
	`type` text NOT NULL,
	`date_of_birth` text,
	`gender` text,
	`nationality` text,
	`passport_number` text,
	`passport_expiry` text,
	`phone` text,
	`room_type` text,
	`rooming_note` text,
	`dietary_note` text,
	`flight_info` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`booking_id`) REFERENCES `bookings`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `departures` (
	`id` text PRIMARY KEY NOT NULL,
	`package_id` text NOT NULL,
	`departure_date` text NOT NULL,
	`return_date` text,
	`seat_capacity` integer DEFAULT 0 NOT NULL,
	`seats_booked` integer DEFAULT 0 NOT NULL,
	`seats_held` integer DEFAULT 0 NOT NULL,
	`adult_price` integer DEFAULT 0 NOT NULL,
	`child_price` integer DEFAULT 0 NOT NULL,
	`infant_price` integer DEFAULT 0 NOT NULL,
	`status` text DEFAULT 'open' NOT NULL,
	`tour_leader` text,
	`notes` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `seat_holds` (
	`id` text PRIMARY KEY NOT NULL,
	`departure_id` text NOT NULL,
	`booking_id` text,
	`seat_count` integer DEFAULT 1 NOT NULL,
	`held_by` text,
	`status` text DEFAULT 'active' NOT NULL,
	`expires_at` text NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`released_at` text,
	FOREIGN KEY (`departure_id`) REFERENCES `departures`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `passenger_documents` (
	`id` text PRIMARY KEY NOT NULL,
	`passenger_id` text NOT NULL,
	`type` text NOT NULL,
	`name` text NOT NULL,
	`r2_key` text NOT NULL,
	`mime_type` text,
	`size_bytes` integer DEFAULT 0 NOT NULL,
	`expires_at` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`passenger_id`) REFERENCES `passengers`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `trip_checklist_items` (
	`id` text PRIMARY KEY NOT NULL,
	`departure_id` text NOT NULL,
	`label` text NOT NULL,
	`category` text,
	`done` integer DEFAULT false NOT NULL,
	`sort_order` integer DEFAULT 0 NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`departure_id`) REFERENCES `departures`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `rooming_assignments` (
	`id` text PRIMARY KEY NOT NULL,
	`departure_id` text NOT NULL,
	`room_number` text NOT NULL,
	`room_type` text,
	`hotel_name` text,
	`passenger_ids` text DEFAULT '[]' NOT NULL,
	`note` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`departure_id`) REFERENCES `departures`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `trip_flights` (
	`id` text PRIMARY KEY NOT NULL,
	`departure_id` text NOT NULL,
	`kind` text DEFAULT 'flight' NOT NULL,
	`code` text,
	`airline` text,
	`origin` text,
	`destination` text,
	`depart_at` text,
	`arrive_at` text,
	`note` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`departure_id`) REFERENCES `departures`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `departure_costs` (
	`id` text PRIMARY KEY NOT NULL,
	`departure_id` text NOT NULL,
	`supplier_id` text,
	`category` text NOT NULL,
	`description` text,
	`estimated_amount` integer DEFAULT 0 NOT NULL,
	`actual_amount` integer DEFAULT 0 NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`departure_id`) REFERENCES `departures`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`supplier_id`) REFERENCES `suppliers`(`id`) ON UPDATE no action ON DELETE set null
);
CREATE TABLE `supplier_payments` (
	`id` text PRIMARY KEY NOT NULL,
	`departure_id` text NOT NULL,
	`supplier_id` text NOT NULL,
	`amount` integer DEFAULT 0 NOT NULL,
	`status` text DEFAULT 'due' NOT NULL,
	`due_date` text,
	`paid_at` text,
	`reference` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`departure_id`) REFERENCES `departures`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`supplier_id`) REFERENCES `suppliers`(`id`) ON UPDATE no action ON DELETE restrict
);
CREATE TABLE `suppliers` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`type` text NOT NULL,
	`contact_name` text,
	`phone` text,
	`email` text,
	`notes` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `audit_logs` (
	`id` text PRIMARY KEY NOT NULL,
	`actor` text,
	`role` text,
	`action` text NOT NULL,
	`entity_type` text NOT NULL,
	`entity_id` text NOT NULL,
	`detail` text,
	`at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `packages` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`destination` text NOT NULL,
	`duration_days` integer DEFAULT 0 NOT NULL,
	`description` text,
	`highlights` text DEFAULT '[]' NOT NULL,
	`itinerary` text DEFAULT '[]' NOT NULL,
	`inclusions` text DEFAULT '[]' NOT NULL,
	`exclusions` text DEFAULT '[]' NOT NULL,
	`adult_price` integer DEFAULT 0 NOT NULL,
	`child_price` integer DEFAULT 0 NOT NULL,
	`infant_price` integer DEFAULT 0 NOT NULL,
	`cover_image_url` text,
	`images` text DEFAULT '[]' NOT NULL,
	`pdf_url` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL
, `publish_status` text DEFAULT 'draft' NOT NULL, `featured` integer DEFAULT false NOT NULL);
CREATE TABLE `package_pricing` (
	`id` text PRIMARY KEY NOT NULL,
	`package_id` text NOT NULL,
	`label` text NOT NULL,
	`pricing_type` text DEFAULT 'per_person' NOT NULL,
	`adult_price` integer DEFAULT 0 NOT NULL,
	`child_price` integer DEFAULT 0 NOT NULL,
	`infant_price` integer DEFAULT 0 NOT NULL,
	`valid_from` text,
	`valid_to` text,
	`is_default` integer DEFAULT false NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`package_id`) REFERENCES `packages`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `package_itinerary_items` (
	`id` text PRIMARY KEY NOT NULL,
	`package_id` text NOT NULL,
	`day_number` integer DEFAULT 1 NOT NULL,
	`title` text,
	`description` text,
	`meal_included` text DEFAULT '[]' NOT NULL,
	`sort_order` integer DEFAULT 0 NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`package_id`) REFERENCES `packages`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `package_media` (
	`id` text PRIMARY KEY NOT NULL,
	`package_id` text NOT NULL,
	`kind` text DEFAULT 'image' NOT NULL,
	`url` text NOT NULL,
	`alt` text,
	`caption` text,
	`sort_order` integer DEFAULT 0 NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`package_id`) REFERENCES `packages`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `package_departure_dates` (
	`id` text PRIMARY KEY NOT NULL,
	`package_id` text NOT NULL,
	`departure_date` text NOT NULL,
	`return_date` text,
	`seat_capacity` integer DEFAULT 0 NOT NULL,
	`adult_price` integer DEFAULT 0 NOT NULL,
	`child_price` integer DEFAULT 0 NOT NULL,
	`infant_price` integer DEFAULT 0 NOT NULL,
	`status` text DEFAULT 'scheduled' NOT NULL,
	`published` integer DEFAULT false NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL,
	FOREIGN KEY (`package_id`) REFERENCES `packages`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `customers` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`phone` text NOT NULL,
	`email` text,
	`type` text DEFAULT 'individual' NOT NULL,
	`city` text,
	`notes` text,
	`lead_id` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `lead_activities` (
	`id` text PRIMARY KEY NOT NULL,
	`lead_id` text NOT NULL,
	`type` text NOT NULL,
	`text` text NOT NULL,
	`user` text DEFAULT 'system' NOT NULL,
	`at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `lead_sources` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`description` text,
	`active` integer DEFAULT true NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `lead_follow_ups` (
	`id` text PRIMARY KEY NOT NULL,
	`lead_id` text NOT NULL,
	`due_at` text NOT NULL,
	`channel` text DEFAULT 'whatsapp' NOT NULL,
	`note` text,
	`done` integer DEFAULT false NOT NULL,
	`done_at` text,
	`done_by` text,
	`created_by` text DEFAULT 'system' NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `invoice_items` (
	`id` text PRIMARY KEY NOT NULL,
	`invoice_id` text NOT NULL,
	`quotation_item_id` text,
	`description` text NOT NULL,
	`quantity` integer DEFAULT 1 NOT NULL,
	`unit_price` integer DEFAULT 0 NOT NULL,
	`amount` integer DEFAULT 0 NOT NULL,
	`sort_order` integer DEFAULT 0 NOT NULL
);
CREATE TABLE `invoices` (
	`id` text PRIMARY KEY NOT NULL,
	`number` text NOT NULL,
	`booking_id` text,
	`quotation_id` text,
	`customer_id` text,
	`customer_name` text NOT NULL,
	`package_name` text,
	`status` text DEFAULT 'draft' NOT NULL,
	`issue_date` text,
	`due_date` text,
	`subtotal` integer DEFAULT 0 NOT NULL,
	`discount` integer DEFAULT 0 NOT NULL,
	`total` integer DEFAULT 0 NOT NULL,
	`deposit_amount` integer DEFAULT 0 NOT NULL,
	`paid_amount` integer DEFAULT 0 NOT NULL,
	`balance_due` integer DEFAULT 0 NOT NULL,
	`notes` text,
	`created_by` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `payment_reminders` (
	`id` text PRIMARY KEY NOT NULL,
	`invoice_id` text NOT NULL,
	`channel` text DEFAULT 'whatsapp' NOT NULL,
	`message` text NOT NULL,
	`sent_at` text DEFAULT (datetime('now')) NOT NULL,
	`sent_by` text
);
CREATE TABLE `payments` (
	`id` text PRIMARY KEY NOT NULL,
	`invoice_id` text NOT NULL,
	`amount` integer NOT NULL,
	`method` text DEFAULT 'bank_transfer' NOT NULL,
	`status` text DEFAULT 'pending_verification' NOT NULL,
	`paid_at` text DEFAULT (datetime('now')) NOT NULL,
	`verified_by` text,
	`verified_at` text,
	`proof_key` text,
	`proof_uploaded` integer DEFAULT false NOT NULL,
	`reference` text,
	`notes` text,
	`created_by` text
);
CREATE TABLE `quotations` (
	`id` text PRIMARY KEY NOT NULL,
	`number` text NOT NULL,
	`customer_name` text NOT NULL,
	`customer_phone` text,
	`package_name` text,
	`destination` text,
	`pax_adult` integer DEFAULT 0 NOT NULL,
	`pax_child` integer DEFAULT 0 NOT NULL,
	`pax_infant` integer DEFAULT 0 NOT NULL,
	`departure_date` text,
	`status` text DEFAULT 'draft' NOT NULL,
	`valid_until` text,
	`subtotal` integer DEFAULT 0 NOT NULL,
	`discount` integer DEFAULT 0 NOT NULL,
	`total` integer DEFAULT 0 NOT NULL,
	`lead_id` text,
	`created_by` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `refunds` (
	`id` text PRIMARY KEY NOT NULL,
	`number` text NOT NULL,
	`invoice_id` text NOT NULL,
	`payment_id` text,
	`amount` integer NOT NULL,
	`reason` text NOT NULL,
	`status` text DEFAULT 'requested' NOT NULL,
	`requested_at` text DEFAULT (datetime('now')) NOT NULL,
	`processed_at` text,
	`processed_by` text
);
CREATE TABLE `alerts` (
	`id` text PRIMARY KEY NOT NULL,
	`kind` text NOT NULL,
	`severity` text DEFAULT 'info' NOT NULL,
	`title` text NOT NULL,
	`message` text NOT NULL,
	`entity_type` text,
	`entity_id` text,
	`is_read` integer DEFAULT false NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `site_banners` (
	`id` text PRIMARY KEY NOT NULL,
	`title` text NOT NULL,
	`subtitle` text DEFAULT '' NOT NULL,
	`cta_label` text DEFAULT '' NOT NULL,
	`cta_href` text DEFAULT '/site/packages' NOT NULL,
	`start_at` text,
	`end_at` text,
	`active` integer DEFAULT true NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `site_pages` (
	`id` text PRIMARY KEY NOT NULL,
	`slug` text NOT NULL,
	`title` text NOT NULL,
	`content` text DEFAULT '' NOT NULL,
	`status` text DEFAULT 'draft' NOT NULL,
	`scheduled_at` text,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `site_seo` (
	`slug` text PRIMARY KEY NOT NULL,
	`meta_title` text DEFAULT '' NOT NULL,
	`meta_description` text DEFAULT '' NOT NULL,
	`keywords` text DEFAULT '' NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `mcp_audit_logs` (
	`id` text PRIMARY KEY NOT NULL,
	`token_id` text,
	`tool` text NOT NULL,
	`arguments` text,
	`outcome` text NOT NULL,
	`denied_reason` text,
	`duration_ms` integer DEFAULT 0 NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `mcp_tokens` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`token_hash` text NOT NULL,
	`token_preview` text NOT NULL,
	`role` text NOT NULL,
	`scopes` text DEFAULT '[]' NOT NULL,
	`status` text DEFAULT 'active' NOT NULL,
	`created_by` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`last_used_at` text,
	`expires_at` text NOT NULL,
	`calls_last_30d` integer DEFAULT 0 NOT NULL
);
CREATE TABLE `mcp_rate_limits` (
	`id` text PRIMARY KEY NOT NULL,
	`token_id` text NOT NULL,
	`window_start` text NOT NULL,
	`count` integer DEFAULT 0 NOT NULL
);
CREATE TABLE `account` (
	`id` text PRIMARY KEY NOT NULL,
	`accountId` text NOT NULL,
	`providerId` text NOT NULL,
	`userId` text NOT NULL,
	`accessToken` text,
	`refreshToken` text,
	`idToken` text,
	`accessTokenExpiresAt` integer,
	`refreshTokenExpiresAt` integer,
	`scope` text,
	`password` text,
	`createdAt` integer NOT NULL,
	`updatedAt` integer NOT NULL,
	FOREIGN KEY (`userId`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `session` (
	`id` text PRIMARY KEY NOT NULL,
	`expiresAt` integer NOT NULL,
	`token` text NOT NULL,
	`createdAt` integer NOT NULL,
	`updatedAt` integer NOT NULL,
	`ipAddress` text,
	`userAgent` text,
	`userId` text NOT NULL,
	FOREIGN KEY (`userId`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `user` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`email` text NOT NULL,
	`emailVerified` integer DEFAULT false NOT NULL,
	`image` text,
	`role` text DEFAULT 'sales' NOT NULL,
	`status` text DEFAULT 'active' NOT NULL,
	`createdAt` integer NOT NULL,
	`updatedAt` integer NOT NULL
);
CREATE TABLE `verification` (
	`id` text PRIMARY KEY NOT NULL,
	`identifier` text NOT NULL,
	`value` text NOT NULL,
	`expiresAt` integer NOT NULL,
	`createdAt` integer NOT NULL,
	`updatedAt` integer NOT NULL
);
CREATE TABLE `staff_audit_logs` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text,
	`actor_email` text NOT NULL,
	`action` text NOT NULL,
	`detail` text,
	`ip` text,
	`user_agent` text,
	`outcome` text DEFAULT 'success' NOT NULL,
	`createdAt` integer NOT NULL
);
CREATE TABLE `app_settings` (
	`key` text PRIMARY KEY NOT NULL,
	`value` text NOT NULL,
	`updated_by` text,
	`updatedAt` integer NOT NULL
);
CREATE TABLE `bank_accounts` (
	`id` text PRIMARY KEY NOT NULL,
	`bank_name` text NOT NULL,
	`account_no` text NOT NULL,
	`holder` text NOT NULL,
	`is_default` integer DEFAULT false NOT NULL,
	`created_by` text,
	`createdAt` integer NOT NULL
);
CREATE TABLE `numbering_rules` (
	`id` text PRIMARY KEY NOT NULL,
	`doc` text NOT NULL,
	`prefix` text NOT NULL,
	`digits` integer DEFAULT 6 NOT NULL,
	`next_no` integer DEFAULT 1 NOT NULL,
	`reset_on` text DEFAULT 'year' NOT NULL,
	`last_reset_at` integer,
	`updatedAt` integer NOT NULL
);
CREATE TABLE `api_tokens` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`token_hash` text NOT NULL,
	`token_preview` text NOT NULL,
	`created_by` text,
	`scopes` text DEFAULT '[]' NOT NULL,
	`status` text DEFAULT 'active' NOT NULL,
	`last_used_at` integer,
	`expires_at` integer NOT NULL,
	`createdAt` integer NOT NULL
);
CREATE TABLE `settings_audit_logs` (
	`id` text PRIMARY KEY NOT NULL,
	`actor` text,
	`role` text,
	`module` text NOT NULL,
	`field` text NOT NULL,
	`before_value` text,
	`after_value` text,
	`change_type` text NOT NULL,
	`at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `notification_templates` (
	`id` text PRIMARY KEY NOT NULL,
	`code` text NOT NULL,
	`name_ms` text NOT NULL,
	`name_en` text NOT NULL,
	`channel` text NOT NULL,
	`subject` text DEFAULT '' NOT NULL,
	`body` text NOT NULL,
	`enabled` integer DEFAULT true NOT NULL,
	`updated_by` text,
	`updatedAt` integer NOT NULL
);
CREATE TABLE `ai_conversations` (
	`id` text PRIMARY KEY NOT NULL,
	`staff_id` text NOT NULL,
	`title` text DEFAULT 'New chat' NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `ai_messages` (
	`id` text PRIMARY KEY NOT NULL,
	`conversation_id` text NOT NULL,
	`role` text NOT NULL,
	`content` text NOT NULL,
	`tool_calls` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `followup_stages` (
	`id` text PRIMARY KEY NOT NULL,
	`code` text NOT NULL,
	`name_ms` text NOT NULL,
	`name_en` text NOT NULL,
	`offset_days` integer DEFAULT 1 NOT NULL,
	`template_id` text,
	`order` integer DEFAULT 1 NOT NULL,
	`active` integer DEFAULT true NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL
, `due_hour_kl` integer DEFAULT 10 NOT NULL);
CREATE TABLE `followup_activities` (
	`id` text PRIMARY KEY NOT NULL,
	`lead_id` text NOT NULL,
	`stage` text NOT NULL,
	`type` text NOT NULL,
	`text` text NOT NULL,
	`confirmed` integer DEFAULT false NOT NULL,
	`user` text DEFAULT 'system' NOT NULL,
	`at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `customer_notes` (
	`id` text PRIMARY KEY NOT NULL,
	`lead_id` text NOT NULL,
	`text` text NOT NULL,
	`created_by` text NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `whatsapp_templates` (
	`id` text PRIMARY KEY NOT NULL,
	`code` text NOT NULL,
	`name` text NOT NULL,
	`locale` text NOT NULL,
	`body` text NOT NULL,
	`stage` text,
	`active` integer DEFAULT true NOT NULL,
	`created_by` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `import_batches` (
	`id` text PRIMARY KEY NOT NULL,
	`file_name` text NOT NULL,
	`total_rows` integer DEFAULT 0 NOT NULL,
	`inserted_rows` integer DEFAULT 0 NOT NULL,
	`duplicate_rows` integer DEFAULT 0 NOT NULL,
	`failed_rows` integer DEFAULT 0 NOT NULL,
	`created_by` text NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE `import_errors` (
	`id` text PRIMARY KEY NOT NULL,
	`batch_id` text NOT NULL,
	`row_number` integer NOT NULL,
	`raw_data` text,
	`reason` text NOT NULL,
	`created_at` text DEFAULT (datetime('now')) NOT NULL
);
CREATE TABLE IF NOT EXISTS "leads" (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`phone` text NOT NULL,
	`email` text,
	`destination` text,
	`pax` integer DEFAULT 1 NOT NULL,
	`budget` integer DEFAULT 0 NOT NULL,
	`stage` text DEFAULT 'new' NOT NULL,
	`source_id` text,
	`assigned_to` text,
	`next_follow_up` text,
	`last_activity_at` text DEFAULT (datetime('now')) NOT NULL,
	`notes` text,
	`customer_id` text,
	`created_at` text DEFAULT (datetime('now')) NOT NULL,
	`updated_at` text DEFAULT (datetime('now')) NOT NULL,
	`owner_user_id` text NOT NULL,
	`followup_status` text,
	`followup_state` text,
	`next_followup_at` text
, `phone_normalized` text, `followup_stage` text, `followup_stage_at` text, `paused_at` text, `pause_reason` text, `escalated_at` text, `last_contacted_at` text, `followup_completed_at` text);
DELETE FROM sqlite_sequence;
CREATE INDEX `booking_history_booking_idx` ON `booking_history` (`booking_id`);
CREATE INDEX `booking_history_at_idx` ON `booking_history` (`at`);
CREATE UNIQUE INDEX `bookings_reference_unique` ON `bookings` (`reference`);
CREATE INDEX `bookings_status_idx` ON `bookings` (`status`);
CREATE INDEX `bookings_payment_status_idx` ON `bookings` (`payment_status`);
CREATE INDEX `bookings_departure_idx` ON `bookings` (`departure_id`);
CREATE INDEX `passengers_booking_idx` ON `passengers` (`booking_id`);
CREATE INDEX `passengers_passport_idx` ON `passengers` (`passport_number`);
CREATE INDEX `departures_package_idx` ON `departures` (`package_id`);
