INSERT INTO "packages" ("id","name","destination","duration_days","description","highlights","itinerary","inclusions","exclusions","adult_price","child_price","infant_price","cover_image_url","images","pdf_url","created_at","updated_at","publish_status","featured") VALUES('5a479e05-501d-4548-b186-cf936ab3af0f','TURKIYE CLASSIC 9H7M (2027)','Turkiye',9,'Jelajah Turkiye Classic 9 hari 7 malam merangkumi Istanbul, Bolu, Ankara, Cappadocia, Pamukkale dan Bursa. Pelepasan berkumpulan sepanjang 2027 (Musim Spring, Premiere & Cuti Sekolah). Harga promo bermula RM4,899 seorang. Program tertakluk kepada pertukaran berdasarkan musim semasa.','["Anıtkabir, makam Mustafa Kemal Atatürk di Ankara","Cappadocia City Tour & Underground City of Cardak","Hot Air Balloon (optional) di Cappadocia & Pamukkale","Antique City of Hierapolis (Cotton Castle)","Pelayaran Bosphorus Cruise & Spice Bazaar","Tulip Garden Festival di Emirgan Park (April sahaja)","Blue Mosque, Hagia Sophia, Hippodrome & Topkapi Palace (photostop)","Grand Bazaar & Dataran Taksim","Makanan HALAL & pengangkutan berhawa dingin","Tour Escort dari Malaysia"]','[]','["Tiket Penerbangan Pergi Balik","Penginapan hotel di lokasi dinyatakan","Makan HALAL sesuai aturcara","Pengangkutan berhawa dingin","Pemandu Pelancong yang berpengalaman","Tour Escort dari Malaysia","Bayaran masuk tempat lawatan seperti di itinerary","Bagasi"]','["Tiket Topkapi","Tipping untuk petugas di Turki RM200/peserta","Optional Tour (contoh: Hot Air Balloon)","Travel Insurans","Cable car ticket di Pierre Loti Hill","Single supplement RM1,000","Deposit RM1,000/peserta (baki 45 hari sebelum berlepas)"]',4899,4699,1000,NULL,'[]',NULL,'2026-11-18T03:56:12.963Z','2026-11-18T03:56:12.963Z','draft',0);
INSERT INTO "packages" ("id","name","destination","duration_days","description","highlights","itinerary","inclusions","exclusions","adult_price","child_price","infant_price","cover_image_url","images","pdf_url","created_at","updated_at","publish_status","featured") VALUES('3ebaede6-112c-4e2a-bd1c-28fd591832f1','Korea Winter – Jelajah Korea! (6 Hari 4 Malam)','Korea',6,'Jelajah Korea Winter! 6 Hari 4 Malam — Seoul • Nami Island • Elysian Gangchon Ski Resort. Pelepasan Berkumpulan 2027, dari RM3,888/seorang. Tarikh pelepasan: 09 Jan–14 Jan 2027 (RM3,999), 27 Jan–01 Feb 2027 (RM3,888), 28 Jan–02 Feb 2027 (RM3,888). Harga asal RM4,190. Kanak-kanak diskaun RM200 (mestilah peserta no. 3 dalam bilik; jika tidak dikira dewasa). Infant RM500. Penginapan single tambahan RM1,000. Deposit RM500 seorang; baki 45 hari sebelum berlepas. Tertakluk kepada pertukaran dan notis semasa musim sejuk (itinerary akan berubah ke Ski Resort).','["Elysian Gangchon Ski Resort & gondola","Gyeongbokgung Palace dengan Hanbok","Nami Island","Namsan Tower & Love Padlock Wall","Eunpyeong Traditional Hanok Village","Seaweed Museum & pengalaman membuat Kimchi","Insadong Cultural Street","COEX Mall & Starfield Library","Hongdae Picasso & Busking Street","Namdaemun Market & Myeong-dong Fashion Street"]','[]','["Tiket penerbangan antarabangsa","Penginapan hotel 3 bintang","Tiket masuk seperti dalam itinerary","Pengangkutan sepanjang lawatan","Gondola di Ski Resort","Makanan seperti dalam itinerary","Tour Guide berbahasa Inggeris","Visa K-ETA"]','["Insurans perjalanan","Perbelanjaan peribadi","Tipping RM150","Optional tour","Sewaan peralatan ski (USD35) dan pakaian ski (USD15)","Penginapan single tambahan RM1,000"]',3888,3688,500,NULL,'[]',NULL,'2026-11-18T04:10:26.149Z','2026-11-18T04:10:26.149Z','published',0);
INSERT INTO "packages" ("id","name","destination","duration_days","description","highlights","itinerary","inclusions","exclusions","adult_price","child_price","infant_price","cover_image_url","images","pdf_url","created_at","updated_at","publish_status","featured") VALUES('408bb316-75ea-4bcf-91f3-e0ccf245143a','TRANS JAVA 9D8N - Jakarta • Bandung • Semarang • Jogja • Bromo • Malang • Surabaya • Madura','Indonesia',9,'Jelajah Indonesia merentasi Pulau Jawa selama 9 hari 8 malam. RRM2,999 per dewasa.','["Bromo Sunrise – Semeru Lawang – Savana Tour","Merapi Jeep Tour","Borobudur Temple photo stop","Lawang Sewu Semarang","Lembang Farm House & Floating Market","Pelancongan keretapi Jakarta–Bandung","Jambatan Suramadu ke Madura","Shopping di Jalan Malioboro, Cihampelas & Pasar Baru"]','[]','["Tiket penerbangan pergi balik","Tiket keretapi","Makan minum sesuai aturcara","Pengangkutan sepanjang program","8 malam penginapan","Pemandu pelancongan","Bayaran masuk tempat lawatan","Air mineral dalam bas","Insuran Group","Bagasi 20KG"]','["Perbelanjaan peribadi","Tipping RM180/seorang","Single supplement RM1,000"]',2999,2799,500,NULL,'[]',NULL,'2026-11-18T06:42:55.849Z','2026-11-18T06:42:55.849Z','published',0);
INSERT INTO "package_itinerary_items" ("id","package_id","day_number","title","description","meal_included","sort_order","created_at") VALUES('c9f25040-b19b-4b44-9b65-dc8c4929bb6b','5a479e05-501d-4548-b186-cf936ab3af0f',1,'Kuala Lumpur – Istanbul – Bolu','Berkumpul di KLIA 4 jam sebelum waktu berlepas. Sesi taklimat dan urusan check in. Setiba di Airport Istanbul disambut oleh wakil kami, bertolak ke Bolu. Makan malam dan bermalam di Bolu.','["Makan Malam (MOB)","Makan Malam (D)"]',1,'2026-11-18T03:56:12.963Z');
INSERT INTO "package_itinerary_items" ("id","package_id","day_number","title","description","meal_included","sort_order","created_at") VALUES('fb9ad556-acdf-4477-80ac-e31ad540c90e','5a479e05-501d-4548-b186-cf936ab3af0f',2,'Bolu – Ankara – Salt Lake – Cappadocia','Setelah sarapan dan check out dari hotel, peserta menuju Ankara untuk mengunjungi Anıtkabir, makam Mustafa Kemal Atatürk. Kemudian meneruskan perjalanan ke Salt Lake. Selepas makan tengahari, meneruskan perjalanan ke Cappadocia untuk makan malam dan check-in hotel.','["Sarapan (B)","Makan Tengahari (L)","Makan Malam (D)"]',2,'2026-11-18T03:56:12.963Z');
INSERT INTO "package_itinerary_items" ("id","package_id","day_number","title","description","meal_included","sort_order","created_at") VALUES('ad23bbe2-e570-4dad-b4a7-c3c505af0bb6','5a479e05-501d-4548-b186-cf936ab3af0f',3,'Cappadocia','Acara Hot Air Balloon (OPTIONAL). Setelah selesai, sarapan di hotel, bertolak untuk Cappadocia City Tour. Lawatan ke Underground City of Cardak, Ucisar Village, Panoramic View, Hand Made Carpet dan Pottery Showroom, serta Jewellery Shop. Makan malam dan bermalam di Cappadocia.','["Sarapan (B)","Makan Tengahari (L)","Makan Malam (D)"]',3,'2026-11-18T03:56:12.963Z');
INSERT INTO "package_itinerary_items" ("id","package_id","day_number","title","description","meal_included","sort_order","created_at") VALUES('6fdf814b-e307-4323-a183-bbcbafb4137b','5a479e05-501d-4548-b186-cf936ab3af0f',4,'Cappadocia – Pamukkale','Selepas sarapan dan check out, bertolak ke Pamukkale. Melawat Caravanserai berdekatan Silk Road. Dalam perjalanan, singgah melawat Mevlana Museum dan Masjid. Makan malam dan bermalam di Pamukkale.','["Sarapan (B)","Makan Tengahari (L)","Makan Malam (D)"]',4,'2026-11-18T03:56:12.963Z');
INSERT INTO "package_itinerary_items" ("id","package_id","day_number","title","description","meal_included","sort_order","created_at") VALUES('9eedffc4-8c92-4944-aa8a-433de2195bc8','5a479e05-501d-4548-b186-cf936ab3af0f',5,'Pamukkale – Bursa','Acara Hot Air Balloon di awal pagi (OPTIONAL). Sarapan pagi di hotel dan Shopping di Turkish Delight Bazaar serta Tour di Antique City of Hierapolis (Cotton Castle). Meneruskan perjalanan ke Bursa untuk makan malam dan bermalam.','["Sarapan (B)","Makan Tengahari (L)","Makan Malam (D)"]',5,'2026-11-18T03:56:12.963Z');
INSERT INTO "package_itinerary_items" ("id","package_id","day_number","title","description","meal_included","sort_order","created_at") VALUES('8eccfb6e-afba-4935-bc2f-518290c57c84','5a479e05-501d-4548-b186-cf936ab3af0f',6,'Bursa – Istanbul','Sarapan pagi di hotel. Lawatan ke Grand Mosque di Bursa yang terkenal dengan 20 kubah dan kaligrafi, diikuti Kozahan (Bazar Sutera). Seterusnya Masjid Çamlıca. Setibanya di Istanbul, lawatan ke leather show, pelayaran di sepanjang Selat Bosphorus dan shopping di Spice Bazaar. Makan malam dan check in hotel.','["Sarapan (B)","Makan Tengahari (L)","Makan Malam (D)"]',6,'2026-11-18T03:56:12.963Z');
INSERT INTO "package_itinerary_items" ("id","package_id","day_number","title","description","meal_included","sort_order","created_at") VALUES('db74ee72-f7a7-420e-909f-3515668e4db7','5a479e05-501d-4548-b186-cf936ab3af0f',7,'Istanbul','Selepas sarapan, menikmati Tulip Garden Festival di Emirgan Park (APRIL SAHAJA). Seterusnya kawasan Sultan Ahmed termasuk Blue Mosque, Hagia Sophia (waktu solat), Hippodrome dan halaman pertama Istana Topkapi (photostop di luar sahaja). Masa bebas di Dataran Taksim, makan malam dan kembali ke hotel.','["Sarapan (B)","Makan Tengahari (L)","Makan Malam (D)"]',7,'2026-11-18T03:56:12.963Z');
INSERT INTO "package_itinerary_items" ("id","package_id","day_number","title","description","meal_included","sort_order","created_at") VALUES('79b71a75-13eb-43bb-8767-c4f9490d267d','5a479e05-501d-4548-b186-cf936ab3af0f',8,'Istanbul – Kuala Lumpur','Sarapan di hotel dan check out. Menuju ke Pierre Loti Hill dengan menaiki kereta cable (ticket exclude), menjelajah Masjid Sultan Eyup dan mengunjungi Grand Bazaar. Selepas itu bertolak ke airport untuk pulang ke tanah air.','["Sarapan (B)","Makan Tengahari (L)","Makan Dalam Penerbangan (MOB)"]',8,'2026-11-18T03:56:12.963Z');
INSERT INTO "package_itinerary_items" ("id","package_id","day_number","title","description","meal_included","sort_order","created_at") VALUES('7c00b98a-828e-41f1-a1b0-d6944e0f9b62','5a479e05-501d-4548-b186-cf936ab3af0f',9,'Kuala Lumpur','Tiba di KLIA bersama kenangan manis di bumi Turki.','[]',9,'2026-11-18T03:56:12.963Z');
INSERT INTO "package_itinerary_items" ("id","package_id","day_number","title","description","meal_included","sort_order","created_at") VALUES('5a522362-6a7d-4d6b-9f02-17ee57984e24','3ebaede6-112c-4e2a-bd1c-28fd591832f1',1,'Kuala Lumpur – Seoul | MOB','Peserta berkumpul di KLIA 4 jam sebelum waktu penerbangan untuk urusan daftar masuk bagasi, taklimat ringkas dan sesi bergambar berkumpulan. Seterusnya, peserta berlepas menuju ke Seoul.','["MOB"]',1,'2026-11-18T04:10:26.149Z');
INSERT INTO "package_itinerary_items" ("id","package_id","day_number","title","description","meal_included","sort_order","created_at") VALUES('c76b6c30-8120-4492-ae1d-7433e1b962cb','3ebaede6-112c-4e2a-bd1c-28fd591832f1',2,'Seoul – Nami Island – Ski Resort | L/D','Setibanya di Seoul pada jam 6:30 pagi, peserta bertemu dengan pemandu pelancong sebelum memulakan perjalanan ke Nami Island, pulau yang terkenal dengan suasana alam semula jadi dan pemandangan indah. Selesai lawatan, perjalanan diteruskan ke Ski Resort untuk menikmati pengalaman menaiki gondola sambil melihat pemandangan kawasan pergunungan. Sewaan peralatan ski (USD35) dan pakaian ski (USD15) tidak termasuk. Selesai aktiviti, peserta kembali ke Seoul untuk daftar masuk hotel dan berehat.','["Lunch","Dinner"]',2,'2026-11-18T04:10:26.149Z');
INSERT INTO "package_itinerary_items" ("id","package_id","day_number","title","description","meal_included","sort_order","created_at") VALUES('a78ded72-7ebd-4aca-99cd-6cf03d549a2e','3ebaede6-112c-4e2a-bd1c-28fd591832f1',3,'Seoul | B/L/D','Selepas sarapan pagi, peserta memulakan lawatan ke Gyeongbokgung Palace sambil mengenakan Hanbok untuk merasai suasana tradisional Korea. Lawatan diteruskan ke Masjid Antarabangsa Itaewon, diikuti kunjungan ke Seaweed Museum dan pengalaman membuat Kimchi. Pada sebelah petang, peserta menuju ke Namsan Tower & Love Padlock Wall untuk menikmati pemandangan bandar Seoul dan suasana romantik di kawasan ikonik ini.','["Breakfast","Lunch","Dinner"]',3,'2026-11-18T04:10:26.149Z');
INSERT INTO "package_itinerary_items" ("id","package_id","day_number","title","description","meal_included","sort_order","created_at") VALUES('ded0d471-b580-45de-8c73-5e8a5d03459a','3ebaede6-112c-4e2a-bd1c-28fd591832f1',4,'Seoul | B/L/D','Selepas sarapan pagi, peserta menerokai Eunpyeong Traditional Hanok Village yang menampilkan suasana perkampungan tradisional Korea dengan latar pergunungan. Perjalanan diteruskan ke Insadong Cultural Street untuk melihat kedai-kedai tradisional dan barangan tempatan. Peserta kemudian singgah di Amethyst Factory sebelum mengakhiri lawatan di COEX Mall & Starfield Library, antara lokasi membeli-belah dan bergambar yang popular di Seoul.','["Breakfast","Lunch","Dinner"]',4,'2026-11-18T04:10:26.149Z');
INSERT INTO "package_itinerary_items" ("id","package_id","day_number","title","description","meal_included","sort_order","created_at") VALUES('4f42d0ce-1561-4701-a92d-a199eb0fae6d','3ebaede6-112c-4e2a-bd1c-28fd591832f1',5,'Seoul Shopping Tour | B/L/D','Selepas sarapan pagi, peserta memulakan hari dengan mengunjungi Hongdae Picasso & Busking Street, kawasan yang meriah dengan persembahan jalanan dan suasana anak muda Seoul. Seterusnya, peserta dibawa ke Pine Tree Centre dan kedai kosmetik Korea untuk membeli-belah. Lawatan diteruskan ke Shinsegae Duty-Free Department Store, sebelum peserta menikmati masa bebas untuk membeli-belah di Namdaemun Street Market & Myeong-dong Fashion Street.','["Breakfast","Lunch","Dinner"]',5,'2026-11-18T04:10:26.149Z');
INSERT INTO "package_itinerary_items" ("id","package_id","day_number","title","description","meal_included","sort_order","created_at") VALUES('ed69bdec-5263-48d2-bcdd-941ec47e5876','3ebaede6-112c-4e2a-bd1c-28fd591832f1',6,'Seoul – Kuala Lumpur | B','Selepas sarapan pagi, peserta daftar keluar hotel dan singgah di Korean Souvenir Shop untuk mendapatkan cenderamata terakhir. Selesai membeli-belah, peserta bertolak ke lapangan terbang bagi penerbangan pulang ke Kuala Lumpur pada jam 11:00 pagi.','["Breakfast"]',6,'2026-11-18T04:10:26.149Z');
INSERT INTO "package_itinerary_items" ("id","package_id","day_number","title","description","meal_included","sort_order","created_at") VALUES('bd99a6ae-7767-467f-af87-710af02c8a6c','408bb316-75ea-4bcf-91f3-e0ccf245143a',1,'Kuala Lumpur - Jakarta','Tiba di Jakarta, solat di Masjid Istiqlal, melawat Monas. Penginapan di Jakarta.','["MOB","L","D"]',1,'2026-11-18T06:42:55.849Z');
INSERT INTO "package_itinerary_items" ("id","package_id","day_number","title","description","meal_included","sort_order","created_at") VALUES('666880c9-5281-41af-9aaf-102adca641a7','408bb316-75ea-4bcf-91f3-e0ccf245143a',2,'Jakarta - Bandung','Perjalanan ke Bandung dengan keretapi, shopping di Factory Outlet. Penginapan di Bandung.','["B","L","D"]',2,'2026-11-18T06:42:55.849Z');
