INSERT INTO "site_pages" ("id","slug","title","content","status","scheduled_at","updated_at") VALUES('page-97646fe4','turkiye-classic-9h7m-2027','TURKIYE CLASSIC 9H7M — Pelepasan 2027','{"title":"TURKIYE CLASSIC 9H7M — Pelepasan 2027","summary":"Jelajah Turkiye Classic 9 hari 7 malam — Istanbul, Bolu, Ankara, Cappadocia, Pamukkale & Bursa. Pelepasan berkumpulan sepanjang 2027 dengan harga promo dari RM4,899 seorang. Deposit RM1,000/peserta.","blocks":[{"id":"blk-hero","kind":"hero","value":""},{"id":"blk-summary-h","kind":"heading","value":"Ringkasan Pakej"},{"id":"blk-summary","kind":"text","value":"Jelajah Turkiye Classic 9 hari 7 malam — Istanbul, Bolu, Ankara, Cappadocia, Pamukkale & Bursa. Pelepasan berkumpulan sepanjang 2027 dengan harga promo dari RM4,899 seorang. Deposit RM1,000/peserta."},{"id":"blk-high-h","kind":"heading","value":"Sorotan Trip"},{"id":"blk-high","kind":"list","value":"Anıtkabir, makam Mustafa Kemal Atatürk|Cappadocia City Tour & Underground City|Hierapolis (Cotton Castle) & Pamukkale|Bosphorus Cruise & Spice Bazaar|Tulip Garden Festival di Emirgan Park (April sahaja)|Blue Mosque, Hagia Sophia & Grand Bazaar|Makan HALAL sepanjang program|Tour Escort dari Malaysia"},{"id":"blk-itin-h","kind":"heading","value":"Itinerari Hari Demi Hari"},{"id":"blk-itin","kind":"itinerary","value":"Itinerari Hari Demi Hari","data":{"days":[{"dayNumber":1,"title":"Kuala Lumpur – Istanbul – Bolu","description":"Berkumpul di KLIA 4 jam sebelum berlepas, taklimat dan check in. Tiba di Istanbul, bertolak ke Bolu. Makan malam dan bermalam di Bolu.","mealIncluded":["MOB","D"]},{"dayNumber":2,"title":"Bolu – Ankara – Salt Lake – Cappadocia","description":"Lawatan Anıtkabir di Ankara, seterusnya ke Salt Lake dan Cappadocia. Makan malam dan check-in hotel.","mealIncluded":["B","L","D"]},{"dayNumber":3,"title":"Cappadocia","description":"Hot Air Balloon (optional). Cappadocia City Tour: Underground City of Cardak, Ucisar Village, Panoramic View, Carpet & Pottery Showroom, Jewellery Shop.","mealIncluded":["B","L","D"]},{"dayNumber":4,"title":"Cappadocia – Pamukkale","description":"Bertolak ke Pamukkale. Lawatan Caravanserai di Silk Road, Mevlana Museum dan Masjid. Bermalam di Pamukkale.","mealIncluded":["B","L","D"]},{"dayNumber":5,"title":"Pamukkale – Bursa","description":"Hot Air Balloon (optional). Shopping di Turkish Delight Bazaar dan tour Antique City of Hierapolis (Cotton Castle). Bertolak ke Bursa.","mealIncluded":["B","L","D"]},{"dayNumber":6,"title":"Bursa – Istanbul","description":"Grand Mosque Bursa, Kozahan (Bazar Sutera), Masjid Çamlıca, leather show, Bosphorus Cruise dan Spice Bazaar. Check in hotel Istanbul.","mealIncluded":["B","L","D"]},{"dayNumber":7,"title":"Istanbul","description":"Tulip Garden Festival di Emirgan Park (April sahaja). Blue Mosque, Hagia Sophia, Hippodrome, Istana Topkapi (photostop), masa bebas di Dataran Taksim.","mealIncluded":["B","L","D"]},{"dayNumber":8,"title":"Istanbul – Kuala Lumpur","description":"Pierre Loti Hill (cable car ticket exclude), Masjid Sultan Eyup dan Grand Bazaar. Bertolak ke airport.","mealIncluded":["B","L","MOB"]},{"dayNumber":9,"title":"Kuala Lumpur","description":"Tiba di KLIA.","mealIncluded":[]}]}},{"id":"blk-price-h","kind":"heading","value":"Harga"},{"id":"blk-price","kind":"pricing","value":"Harga","data":{"rows":[{"label":"Dewasa (12+)","amount":"RM 4,899"},{"label":"Kanak-kanak (2–11)","amount":"RM 4,699"},{"label":"Bayi (bawah 2)","amount":"RM 1,000"}]}},{"id":"blk-inc-h","kind":"heading","value":"Termasuk & Tidak Termasuk"},{"id":"blk-inc","kind":"list","value":"TERMASUK: Tiket Penerbangan Pergi Balik|TERMASUK: Penginapan hotel di lokasi dinyatakan|TERMASUK: Makan HALAL sesuai aturcara|TERMASUK: Pengangkutan berhawa dingin|TERMASUK: Pemandu Pelancong yang berpengalaman|TERMASUK: Tour Escort dari Malaysia|TERMASUK: Bayaran masuk tempat lawatan seperti di itinerary|TERMASUK: Bagasi|TIDAK TERMASUK: Tiket Topkapi|TIDAK TERMASUK: Tipping untuk petugas di Turki RM200/peserta|TIDAK TERMASUK: Optional Tour (Hot Air Balloon)|TIDAK TERMASUK: Travel Insurans|TIDAK TERMASUK: Cable car ticket di Pierre Loti Hill|TIDAK TERMASUK: Single supplement RM1,000"},{"id":"blk-cta","kind":"cta","value":"Tempah Sekarang"}]}','draft',NULL,'2026-11-18 03:56:13');
INSERT INTO "site_pages" ("id","slug","title","content","status","scheduled_at","updated_at") VALUES('page-3a96a665','korea-winter-jelajah-korea-6-hari-4-malam','Korea Winter – Jelajah Korea! 6 Hari 4 Malam','{"title":"Korea Winter – Jelajah Korea! 6 Hari 4 Malam","summary":"Jelajah Korea Winter! 6 Hari 4 Malam — Seoul • Nami Island • Elysian Gangchon Ski Resort. Pelepasan Berkumpulan 2027 dari RM3,888/seorang (dewasa), RM3,688 (kanak-kanak), RM500 (infant). Termasuk tiket penerbangan antarabangsa, hotel 3 bintang, gondola ski, K-ETA dan tour guide. Tarikh: 09 Jan–14 Jan 2027 (RM3,999) · 27 Jan–01 Feb 2027 (RM3,888) · 28 Jan–02 Feb 2027 (RM3,888). Deposit RM500 seorang; baki 45 hari sebelum berlepas.","blocks":[{"id":"blk-hero","kind":"hero","value":""},{"id":"blk-summary-h","kind":"heading","value":"Ringkasan Pakej"},{"id":"blk-summary","kind":"text","value":"Jelajah Korea Winter! 6 Hari 4 Malam — Seoul • Nami Island • Elysian Gangchon Ski Resort. Pelepasan Berkumpulan 2027 dari RM3,888/seorang (dewasa), RM3,688 (kanak-kanak), RM500 (infant). Termasuk tiket penerbangan antarabangsa, hotel 3 bintang, gondola ski, K-ETA dan tour guide. Tarikh: 09 Jan–14 Jan 2027 (RM3,999) · 27 Jan–01 Feb 2027 (RM3,888) · 28 Jan–02 Feb 2027 (RM3,888). Deposit RM500 seorang; baki 45 hari sebelum berlepas."},{"id":"blk-high-h","kind":"heading","value":"Sorotan Trip"},{"id":"blk-high","kind":"list","value":"Elysian Gangchon Ski Resort & gondola|Gyeongbokgung Palace dengan Hanbok|Nami Island|Namsan Tower & Love Padlock Wall|Eunpyeong Traditional Hanok Village|Seaweed Museum & pengalaman membuat Kimchi|Insadong Cultural Street|COEX Mall & Starfield Library|Hongdae Picasso & Busking Street|Namdaemun Market & Myeong-dong Fashion Street"},{"id":"blk-itin-h","kind":"heading","value":"Itinerari Hari Demi Hari"},{"id":"blk-itin","kind":"itinerary","value":"Itinerari Hari Demi Hari","data":{"days":[{"dayNumber":1,"title":"Kuala Lumpur – Seoul | MOB","description":"Peserta berkumpul di KLIA 4 jam sebelum waktu penerbangan untuk urusan daftar masuk bagasi, taklimat ringkas dan sesi bergambar berkumpulan. Seterusnya, peserta berlepas menuju ke Seoul.","mealIncluded":["MOB"]},{"dayNumber":2,"title":"Seoul – Nami Island – Ski Resort | L/D","description":"Setibanya di Seoul pada jam 6:30 pagi, peserta bertemu dengan pemandu pelancong sebelum memulakan perjalanan ke Nami Island, pulau yang terkenal dengan suasana alam semula jadi dan pemandangan indah. Selesai lawatan, perjalanan diteruskan ke Ski Resort untuk menikmati pengalaman menaiki gondola sambil melihat pemandangan kawasan pergunungan. Sewaan peralatan ski (USD35) dan pakaian ski (USD15) tidak termasuk. Selesai aktiviti, peserta kembali ke Seoul untuk daftar masuk hotel dan berehat.","mealIncluded":["Lunch","Dinner"]},{"dayNumber":3,"title":"Seoul | B/L/D","description":"Selepas sarapan pagi, peserta memulakan lawatan ke Gyeongbokgung Palace sambil mengenakan Hanbok untuk merasai suasana tradisional Korea. Lawatan diteruskan ke Masjid Antarabangsa Itaewon, diikuti kunjungan ke Seaweed Museum dan pengalaman membuat Kimchi. Pada sebelah petang, peserta menuju ke Namsan Tower & Love Padlock Wall untuk menikmati pemandangan bandar Seoul dan suasana romantik di kawasan ikonik ini.","mealIncluded":["Breakfast","Lunch","Dinner"]},{"dayNumber":4,"title":"Seoul | B/L/D","description":"Selepas sarapan pagi, peserta menerokai Eunpyeong Traditional Hanok Village yang menampilkan suasana perkampungan tradisional Korea dengan latar pergunungan. Perjalanan diteruskan ke Insadong Cultural Street untuk melihat kedai-kedai tradisional dan barangan tempatan. Peserta kemudian singgah di Amethyst Factory sebelum mengakhiri lawatan di COEX Mall & Starfield Library, antara lokasi membeli-belah dan bergambar yang popular di Seoul.","mealIncluded":["Breakfast","Lunch","Dinner"]},{"dayNumber":5,"title":"Seoul Shopping Tour | B/L/D","description":"Selepas sarapan pagi, peserta memulakan hari dengan mengunjungi Hongdae Picasso & Busking Street, kawasan yang meriah dengan persembahan jalanan dan suasana anak muda Seoul. Seterusnya, peserta dibawa ke Pine Tree Centre dan kedai kosmetik Korea untuk membeli-belah. Lawatan diteruskan ke Shinsegae Duty-Free Department Store, sebelum peserta menikmati masa bebas untuk membeli-belah di Namdaemun Street Market & Myeong-dong Fashion Street.","mealIncluded":["Breakfast","Lunch","Dinner"]},{"dayNumber":6,"title":"Seoul – Kuala Lumpur | B","description":"Selepas sarapan pagi, peserta daftar keluar hotel dan singgah di Korean Souvenir Shop untuk mendapatkan cenderamata terakhir. Selesai membeli-belah, peserta bertolak ke lapangan terbang bagi penerbangan pulang ke Kuala Lumpur pada jam 11:00 pagi.","mealIncluded":["Breakfast"]}]}},{"id":"blk-price-h","kind":"heading","value":"Harga"},{"id":"blk-price","kind":"pricing","value":"Harga","data":{"rows":[{"label":"Dewasa (12+)","amount":"RM 3,888"},{"label":"Kanak-kanak (2–11)","amount":"RM 3,688"},{"label":"Bayi (bawah 2)","amount":"RM 500"}]}},{"id":"blk-inc-h","kind":"heading","value":"Termasuk & Tidak Termasuk"},{"id":"blk-inc","kind":"list","value":"TERMASUK: Tiket penerbangan antarabangsa|TERMASUK: Penginapan hotel 3 bintang|TERMASUK: Tiket masuk seperti dalam itinerary|TERMASUK: Pengangkutan sepanjang lawatan|TERMASUK: Gondola di Ski Resort|TERMASUK: Makanan seperti dalam itinerary|TERMASUK: Tour Guide berbahasa Inggeris|TERMASUK: Visa K-ETA|TIDAK TERMASUK: Insurans perjalanan|TIDAK TERMASUK: Perbelanjaan peribadi|TIDAK TERMASUK: Tipping RM150|TIDAK TERMASUK: Optional tour|TIDAK TERMASUK: Sewaan peralatan ski (USD35) dan pakaian ski (USD15)|TIDAK TERMASUK: Penginapan single tambahan RM1,000"},{"id":"blk-cta","kind":"cta","value":"Tempah Sekarang"}]}','published',NULL,'2026-11-18 04:10:32');
