INSERT INTO "mcp_audit_logs" ("id","token_id","tool","arguments","outcome","denied_reason","duration_ms","created_at") VALUES('5c6adfdf-9b2c-429f-b87b-aa70fcd01c85','66e190aa-7fa3-46f4-a4f9-0c1662cfce30','manage_website_page','{"name":"manage_website_page","arguments":{"id":"shanghai-disneyland","slug":"shanghai-disneyland","title":"Shanghai Disneyland – 6 Hari 4 Malam","content":"{\"title\": \"Shanghai Disneyland – 6 Hari 4 Malam\", \"summary\": \"Pakej Shanghai Disneyland 6H4M, berlepas 19–24 Dis 2026. Promo RM4,190/pax (asal RM4,590). Termasuk tiket Disneyland, 4 malam hotel 4*, tour leader & guide.\", \"blocks\": [{\"id\": \"eaf4d824\", \"kind\": \"hero\", \"value\": \"\"}, {\"id\": \"bd7a2d2d\", \"kind\": \"heading\", \"value\": \"Ringkasan Pakej\"}, {\"id\": \"f1dfecd7\", \"kind\": \"text\", \"value\": \"SHANGHAI DISNEYLAND — 6 Hari 4 Malam. Jelajah Shanghai bersama Nusa Travel: sehari penuh di Shanghai Disneyland, Menara Jin Mao, The Bund, Zhujiajiao Ancient Town dan Nanjing Road. Berlepas 19 Dis 2026, kembali 24 Dis 2026 (musim cuti sekolah).\"}, {\"id\": \"067aecca\", \"kind\": \"heading\", \"value\": \"Sorotan Trip\"}, {\"id\": \"6a15d7ff\", \"kind\": \"list\", \"value\": \"Sehari penuh di Shanghai Disneyland|Menara Jin Mao tingkat 88|Lujiazui Circular Sky Corridor|The Bund & Nanjing Road|Zhujiajiao Ancient Town|Solat di Masjid Pudong, Masjid Songjiang & Masjid Xiaotaoyuan|Starbucks Reserve Roastery & Luijiazui Cruise|Tour leader & guide berpengalaman\"}, {\"id\": \"57c68768\", \"kind\": \"heading\", \"value\": \"Itinerary Hari demi Hari\"}, {\"id\": \"ca687e24\", \"kind\": \"text\", \"value\": \"HARI 1: Kuala Lumpur – Shanghai (MOB). Berkumpul di KLIA2 untuk daftar masuk dan taklimat ringkas sebelum berlepas ke Shanghai. Setibanya, peserta dijemput wakil kami dan dibawa ke hotel untuk berehat.\"}, {\"id\": \"d764f3f6\", \"kind\": \"text\", \"value\": \"HARI 2: Shanghai – Disneyland (B,D). Sarapan di hotel, kemudian ke Shanghai Disneyland untuk menikmati pelbagai permainan dan tarikan sepanjang hari. Bermalam di Shanghai.\"}, {\"id\": \"2031847b\", \"kind\": \"text\", \"value\": \"HARI 3: Shanghai Tour (B,L,D). Menara Jin Mao (tingkat 88), Lujiazui Circular Sky Corridor, 1192 Lane Old Shanghai Style Street, solat di Masjid Pudong, The Bund dan masa bebas di Nanjing Road Pedestrian Street.\"}, {\"id\": \"ea84f03c\", \"kind\": \"text\", \"value\": \"HARI 4: Shanghai (B,L,D). Zhujiajiao Ancient Town, solat di Masjid Songjiang, Wukang Mansion, Shanghai Xintiandi. Makan malam dan bermalam di Shanghai.\"}, {\"id\": \"f608b8be\", \"kind\": \"text\", \"value\": \"HARI 5: Shanghai (B,L,D). Daftar keluar hotel, Starbucks Reserve Roastery Shanghai, Luijiazui Cruise Ship, Chenghuangmiao Commercial District, solat di Masjid Xiaotaoyuan, makan malam dan ke Lapangan Terbang Shanghai untuk penerbangan pulang.\"}, {\"id\": \"ff1e75f3\", \"kind\": \"text\", \"value\": \"HARI 6: Shanghai – Kuala Lumpur (MOB). Penerbangan pulang dan tiba di Kuala Lumpur.\"}, {\"id\": \"a0ce4e29\", \"kind\": \"heading\", \"value\": \"Harga\"}, {\"id\": \"647f1ad5\", \"kind\": \"text\", \"value\": \"Harga asal: RM4,590/pax\\nHarga promo: RM4,190/pax\\nBerlepas: 19 Dec 2026 – 24 Dec 2026 (cuti sekolah)\\n\\nKanak-kanak: diskaun RM200 dari harga dewasa dan mesti menjadi peserta ke-3 dalam bilik; jika tidak dikira dewasa.\\nSingle supplement: +RM800\\nInfant: RM500\\nDeposit: RM1,000/pax, baki 45 hari sebelum berlepas.\"}, {\"id\": \"b4713206\", \"kind\": \"heading\", \"value\": \"Termasuk & Tidak Termasuk\"}, {\"id\": \"2c844049\", \"kind\": \"list\", \"value\": \"TERMASUK: Tiket penerbangan pergi balik|4 malam penginapan 4 bintang|Tiket masuk tempat lawatan|Makan mengikut aturcara|Pengangkutan sepanjang perjalanan|Tour leader & tour guide\"}, {\"id\": \"1caa2a53\", \"kind\": \"list\", \"value\": \"TIDAK TERMASUK: Perbelanjaan peribadi|Tips guide & driver RM100|Insurans peribadi\"}, {\"id\": \"f4e62b10\", \"kind\": \"heading\", \"value\": \"Nota Penting\"}, {\"id\": \"a7f25da5\", \"kind\": \"text\", \"value\": \"Tiket masuk Shanghai Disneyland hanya sah untuk hari Isnin hingga Khamis. Jadual tertakluk kepada perubahan semasa. Harga tertakluk kepada pertukaran dan akan dimaklumkan berdasarkan notis. Program mungkin berubah mengikut musim.\"}, {\"id\": \"4a47fcf1\", \"kind\": \"cta\", \"value\": \"Tempah Sekarang\"}]}","status":"draft"}}','error',replace('Error: Failed query: \012            INSERT INTO site_pages (id, slug, title, content, status, created_at, updated_at)\012            VALUES (?, ?, ?, ?, ?, datetime(''now''), datetime(''now''))\012          \012params: shanghai-disneyland,shanghai-disneyland,Shanghai Disneyland – 6 Hari 4 Malam,{"title": "Shanghai Disneyland – 6 Hari 4 Malam", "summary": "Pakej Shanghai Disneyland 6H4M, berlepas 19–24 Dis 2026. Promo RM4,190/pax (asal RM4,590). Termasuk tiket Disneyland, 4 malam hotel 4*, tour leader & guide.", "blocks": [{"id": "eaf4d824", "kind": "hero", "value": ""}, {"id": "bd7a2d2d", "kind": "heading", "value": "Ringkasan Pakej"}, {"id": "f1dfecd7", "kind": "text", "value": "SHANGHAI DISNEYLAND — 6 Hari 4 Malam. Jelajah Shanghai bersama Nusa Travel: sehari penuh di Shanghai Disneyland, Menara Jin Mao, The Bund, Zhujiajiao Ancient Town dan Nanjing Road. Berlepas 19 Dis 2026, kembali 24 Dis 2026 (musim cuti sekolah)."}, {"id": "067aecca", "kind": "heading", "value": "Sorotan Trip"}, {"id": "6a15d7ff", "kind": "list", "value": "Sehari penuh di Shanghai Disneyland|Menara Jin Mao tingkat 88|Lujiazui Circular Sky Corridor|The Bund & Nanjing Road|Zhujiajiao Ancient Town|Solat di Masjid Pudong, Masjid Songjiang & Masjid Xiaotaoyuan|Starbucks Reserve Roastery & Luijiazui Cruise|Tour leader & guide berpengalaman"}, {"id": "57c68768", "kind": "heading", "value": "Itinerary Hari demi Hari"}, {"id": "ca687e24", "kind": "text", "value": "HARI 1: Kuala Lumpur – Shanghai (MOB). Berkumpul di KLIA2 untuk daftar masuk dan taklimat ringkas sebelum berlepas ke Shanghai. Setibanya, pe