INSERT INTO "ai_messages" ("id","conversation_id","role","content","tool_calls","created_at") VALUES('03ca315b-2e52-4854-b73b-968774f9d8f9','ff1a9947-bd94-4bed-a523-002b327f7d31','assistant',replace('Hi! 👋 Saya di sini untuk bantu kerja CRM dan website ZAQONE Travel.\n\nBoleh saya bantu untuk:\n- Cari customer / lead / booking\n- Buat lead atau booking baru\n- Semak baki invoice\n- Terbitkan package dan page website dari itinerary\n\nCuma bagitahu apa yang anda perlukan.','\n',char(10)),'[]','2026-11-18 04:09:47');
INSERT INTO "ai_messages" ("id","conversation_id","role","content","tool_calls","created_at") VALUES('9bcdbb0f-d190-4993-9abe-60ac19208c49','ff1a9947-bd94-4bed-a523-002b327f7d31','user',replace('now buat ni update pakej baru\n[PDF itinerary dilampirkan — UZTAZ FAIZ 016 - 287 9202 W www.nusatra.com|\nKOREA\nWINTER\nRM3,888DARI\nJelajah Korea!\nPELEPASAN BERKUMPULAN 2027\nSEOUL • NAMI ISLAND • ELYSSIAN SKI RESORT\nDATE | PRICE\n6 HARI 4 MALAM\nKOREA\nWINTER\nPAGE 2\nTARIKH PELEPASAN 2027\nBERLEPAS KETIBAAN HARGA ASAL HARGA PROMO NOTA\nRM 4,19009 JAN 14 JAN RM 3,999…]','\n',char(10)),NULL,'2026-11-18 04:10:14');
INSERT INTO "ai_messages" ("id","conversation_id","role","content","tool_calls","created_at") VALUES('2e638762-8041-4b4f-a2cb-8291ad2902bf','ff1a9947-bd94-4bed-a523-002b327f7d31','assistant',replace('SIAP! ✅ Pakej baru dan page website awam dah berjaya diterbitkan.\n\n**Ringkasan yang dibuat:**\n\n| Item | Butiran |\n|---|---|\n| Nama pakej | Korea Winter – Jelajah Korea! (6 Hari 4 Malam) |\n| Destinasi | Korea (Seoul • Nami Island • Elysian Gangchon Ski Resort) |\n| Harga dewasa | RM3,888 (promo; harga asal RM4,190) |\n| Kanak-kanak | RM3,688 (diskaun RM200, peserta no. 3 dalam bilik) |\n| Infant | RM500 |\n| Tarikh pelepasan 2027 | 9 Jan (RM3,999) · 27 Jan (RM3,888) · 28 Jan (RM3,888) |\n| Itinerary | 6 hari lengkap dimasukkan |\n| Inklusi / eksklusi | Dimasukkan mengikut dokumen |\n\n**Link terus:**\n- 📦 Pakej: https://travelcrm.zaqone.com/site/packages/3ebaede6-112c-4e2a-bd1c-28fd591832f1\n- 🌐 Public web page: https://travelcrm.zaqone.com/site/p/korea-winter-jelajah-korea-6-hari-4-malam\n\nNota: Ski rental (USD35) & pakaian ski (USD15), tipping RM150 dan insurans dimasukkan dalam senarai **tidak termasuk** seperti dalam dokumen asal.\n\nAda lagi nak kemaskini — contohnya tambah departing dates sebagai departures, atau ubah harga?','\n',char(10)),'[{"name":"create_package_from_itinerary","summary":"Package \"Korea Winter – Jelajah Korea! (6 Hari 4 Malam)\" published with 6 itinerary day(s) — live on the website","ok":true,"mutation":true,"url":"/site/packages/3ebaede6-112c-4e2a-bd1c-28fd591832f1","urlLabel":"Lihat pakej · Korea Winter – Jelajah Korea! (6 Hari 4 Malam)"},{"name":"create_website_page","summary":"Page \"Korea Winter – Jelajah Korea! 6 Hari 4 Malam\" published and LIVE at /site/p/korea-winter-jelajah-korea-6-hari-4-malam","ok":true,"mutation":true,"url":"/site/p/korea-winter-jelajah-korea-6-hari-4-malam","urlLabel":"Buka laman · Korea Winter – Jelajah Korea! 6 Hari 4 Malam"}]','2026-11-18 04:10:35');
