INSERT INTO "ai_messages" ("id","conversation_id","role","content","tool_calls","created_at") VALUES('6ecf1172-a1d1-407d-89d6-857529f93bb8','17e4a0a7-4c97-4068-8739-15972d4b370c','assistant',replace('There are currently **no leads in the CRM at all** — not just this week. So nothing new came in.\n\nIf you expected enquiries, a few things to check:\n- Leads may have been captured on another channel (WhatsApp/phone) and not logged yet — I can create them for you if you share the contact details.\n- If you just want, I can also check recent bookings to see if any enquiries converted directly.\n\nWant me to log any new enquiries now?','\n',char(10)),'[{"name":"list_leads","summary":"0 lead(s) found","ok":true},{"name":"list_leads","summary":"0 lead(s) found","ok":true}]','2026-11-18 06:14:37');
