INSERT INTO "ai_messages" ("id","conversation_id","role","content","tool_calls","created_at") VALUES('8dcc6971-9380-4aef-b089-6421ef7e03ad','04cc2ef8-516c-4eed-a298-fe455b600a14','assistant',replace('Tak ada leads baru buat masa ni — senarai leads kosong sama sekali (tiada lead "new" mahupun lead lama dalam sistem).\n\nKalau anda baru dapat enquiry, bagitahu saya nama, nombor telefon, dan destinasi — saya terus boleh log masuk sebagai lead baru.','\n',char(10)),'[{"name":"list_leads","summary":"0 lead(s) found","ok":true},{"name":"list_leads","summary":"0 lead(s) found","ok":true}]','2026-11-18 06:14:51');
